INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'wire', 0, 'lab', 'Первый сигнал', 'Соедините вход A с выходом Y обычным проводом. Элементы здесь не нужны — сигнал можно передавать и по проводу.', '', 'Схватите круглый контакт справа от блока A и отпустите его на контакте слева от Y.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'not', 1, 'lab', 'Инвертор (НЕ)', 'Соберите элемент, который переворачивает сигнал: при A = 0 на выходе 1, при A = 1 — 0.', '', 'У элемента НЕ один вход. Есть и трюк: если у ИЛИ-НЕ соединить оба входа вместе, он тоже станет инвертором.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'and', 2, 'lab', 'Элемент И', 'Лампочка Y горит (1), только когда ОБА входа равны 1.', '', 'Один элемент И решает задачу целиком: единица в «Цели» стоит только в строке 1 1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'or', 3, 'lab', 'Элемент ИЛИ', 'Лампочка Y горит, когда ХОТЯ БЫ ОДИН вход равен 1.', '', 'Можно взять готовый элемент ИЛИ. А можно собрать ИЛИ из И и НЕ — вспомните закон де Моргана: НЕ(НЕ-A И НЕ-B).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'nor', 4, 'lab', 'ИЛИ-НЕ', 'Лампочка Y горит, только когда ОБА входа равны 0.', '', 'Это «НЕ от ИЛИ»: сначала ИЛИ, потом инверсия. Или один готовый элемент ИЛИ-НЕ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'nand', 5, 'lab', 'И-НЕ', 'Лампочка Y горит всегда, КРОМЕ случая, когда оба входа равны 1.', '', '«НЕ от И»: сначала элемент И, затем инвертор на его выходе.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'enable', 6, 'lab', 'Разрешение: пропуск сигнала', 'D — данные, E — разрешение. На выход должно проходить только разрешённое: Y повторяет D, но только при E = 1; при E = 0 на выходе всегда 0.', '', 'Это по-прежнему элемент И: единица только когда оба входа равны 1. Присмотритесь: E здесь работает как ключ, а D — как данные.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'inhibit', 7, 'lab', 'Блокировка: сигнал с запретом', 'Теперь наоборот: сигнал A проходит, только пока B МОЛЧИТ. При B = 1 на выходе всегда 0, что бы ни делал A.', '', 'Сначала переверните B элементом НЕ, затем объедините с A через И: Y = A И НЕ-B.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'dont-care', 8, 'lab', 'Лишние входы', 'Входов три, но схема должна реагировать только на A: при A = 0 на выходе 1, при A = 1 — 0. Что делать с B и C — решайте сами.', '', 'B и C можно вообще не подключать. Инвертор — это НЕ, или NOR с объединёнными входами.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'xor', 9, 'lab', 'Исключающее ИЛИ', 'Лампочка Y горит, когда входы РАЗНЫЕ: ровно один из двух равен 1.', '', 'Формула: (A ИЛИ B) И НЕ(A И B). Соберите обе скобки отдельными элементами, а затем объедините их через И.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'pair', 10, 'lab', 'Пара: сигнал и его тень', 'Соберите схему с ДВУМЯ выходами: Y равен A И B, а nY — его полная противоположность (НЕ(A И B)). Проверяйте оба столбца таблицы сразу.', '', 'Один элемент И даёт Y. Затем пропустите Y через НЕ — получится nY. Второй провод цепляйте прямо к выходу элемента И.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'equals', 11, 'lab', 'Равенство: сравнение битов', 'Лампочка горит, когда входы ОДИНАКОВЫЕ: оба 0 или оба 1. Это проверка «A = B?» — базовая операция сравнения.', '', 'Два пути: либо НЕ от XOR ((A ИЛИ B) И НЕ(A И B), затем НЕ), либо прямая формула: (A И B) ИЛИ (НЕ-A И НЕ-B). Если XNOR уже открыт — есть и третий: один готовый элемент.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'majority', 12, 'lab', 'Хотя бы два', 'Лампочка горит, когда единиц НЕ МЕНЬШЕ ДВУХ из трёх. Такая схема называется мажоритарной.', '', 'Переберите три варианта пары: A И B, или A И C, или B И C. Три элемента И, затем два ИЛИ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 6, 'mux', 13, 'lab', 'Мультиплексор: выбор канала', 'A — переключатель канала: при A = 0 на выход идёт сигнал B, при A = 1 — сигнал C.', '', 'Две ветки: (НЕ-A И B) и (A И C), затем ИЛИ. Сверьтесь с таблицей: в верхней половине Y повторяет B, в нижней — C.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'mux2-ns', 0, 'lab', 'Мультиплексор без инвертора', 'Мультиплексор выбирает один из двух каналов: D0 при S = 0, D1 при S = 1. Инвертора в палитре нет — зато вместе с S приходит и готовый НЕ-S (вход nS).', '', 'Две ветки и ИЛИ: Y = D0·nS ИЛИ D1·S. Ветка «D0 и nS» открыта, пока выбран нулевой канал; ветка «D1 и S» — пока выбран первый.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'mux2-inv', 1, 'lab', 'Инвертирующий мультиплексор', 'Соберите мультиплексор 2→1, у которого на выход идёт ИНВЕРСИЯ выбранного канала: при S = 0 выход равен НЕ-D0, при S = 1 — НЕ-D1.', '', 'Обычный мультиплексор (НЕ-S·D0 ИЛИ S·D1), а на выходе — инвертор. Или сократите: последнее ИЛИ вместе с НЕ — это один элемент ИЛИ-НЕ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'mux2-enable', 2, 'lab', 'Мультиплексор с разрешением', 'Добавьте вход разрешения E: при E = 1 мультиплексор работает как обычно (S = 0 → D0, S = 1 → D1), а при E = 0 выход всегда 0.', '', 'Соберите обычный мультиплексор, а его выход пропустите через элемент И вместе с E — помните «Разрешение: пропуск сигнала» из первого раздела.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'mux-bnotb', 3, 'lab', 'Управляемый инвертор', 'S = 0 — на выход идёт B как есть; S = 1 — на выход идёт НЕ-B. То есть это мультиплексор, у которого каналы — сам B и его инверсия.', '', 'Канал 0 — это B, канал 1 — НЕ-B. Мультиплексор: НЕ-S·B ИЛИ S·НЕ-B. Нужны два инвертора (на S и на B).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'demux2', 4, 'lab', 'Демультиплексор 1→2', 'Данные D нужно «направить» в один из двух выходов: при S = 0 данные идут в Y0, при S = 1 — в Y1. Незадействованный выход должен быть 0.', '', 'Два элемента И: Y0 = D И НЕ-S, Y1 = D И S. Инвертор один — на вход S.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'decoder2', 5, 'lab', 'Дешифратор 2→4', 'Два бита S1 S0 — это номер от 0 до 3. Зажгите ровно один выход с этим номером: Y0 при 00, Y1 при 01, Y2 при 10, Y3 при 11. Данных нет — просто «выбор».', '', 'Каждый выход — элемент И, который «узнаёт» свой код. Для Y0 (код 00) подойдёт один ИЛИ-НЕ: он горит, когда оба входа нули. Для остальных нужны инверторы на нужных входах.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'demux4', 6, 'lab', 'Демультиплексор 1→4', 'Теперь два бита выбора S1 и S0 задают один из ЧЕТЫРЁХ выходов: Y0…Y3. Данные D идут только в выбранный выход.', '', 'Декодер выбора: Y0 = D·НЕ-S1·НЕ-S0, Y1 = D·НЕ-S1·S0, Y2 = D·S1·НЕ-S0, Y3 = D·S1·S0. Два инвертора на S1 и S0, дальше восемь элементов И (по два на выход).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'decoder3', 7, 'lab', 'Дешифратор 3→8', 'Три бита S2 S1 S0 — номер от 0 до 7. Зажгите ровно один из восьми выходов Y0…Y7 с этим номером.', '', 'Не собирайте восемь «трёхвходовых И» с нуля. Сначала дешифратор 2→4 по S1 S0 (четыре И), а затем каждый из его выходов умножьте на S2 или НЕ-S2 — получится восемь.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'encoder4', 8, 'lab', 'Приоритетный шифратор 4→2', 'Шифратор — наоборот дешифратору: по входам I0…I3 выдаёт номер сработавшего. Если горят сразу несколько, побеждает СТАРШИЙ. Y1 Y0 — номер, V = 1, когда горит хотя бы один вход (иначе номер не имеет смысла).', '', 'Старший бит номера: Y1 = I2 ИЛИ I3. Младший: Y0 = I3 ИЛИ (I1 И НЕ-I2) — единица I1 считается, только если I2 молчит. V — ИЛИ всех четырёх (можно взять готовое I2 ИЛИ I3 = Y1).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'mux2-bus', 9, 'lab', 'Мультиплексор двух шин', 'Теперь выбираем не бит, а целое двухбитное число: шина A (A1 A0) или шина B (B1 B0). При S = 0 на выход Y1 Y0 идёт A, при S = 1 — B. Каждый бит выбирается отдельно, но по общему S.', '', 'Два одинаковых мультиплексора 2→1: один на старшие биты (A1, B1), другой на младшие (A0, B0). Инвертор для S нужен только один — его выход идёт к обоим.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'mux4', 10, 'lab', 'Мультиплексор 4→1', 'Четыре канала D0…D3 и два бита выбора S1 S0 (номер канала). На выход идёт тот канал, чей номер выставлен на S1 S0.', '', 'Соберите дерево из трёх мультиплексоров 2→1: два первых выбирают по S0 из пар (D0, D1) и (D2, D3), третий — по S1 между результатами. Инверторы нужны только на S0 и S1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 7, 'mux2-nor', 11, 'lab', 'Мультиплексор только из ИЛИ-НЕ', 'Финальная головоломка: соберите мультиплексор 2→1 (S = 0 → D0, S = 1 → D1) из ОДНИХ элементов ИЛИ-НЕ. Ни И, ни ИЛИ, ни НЕ в палитре нет.', '', 'ИЛИ-НЕ с соединёнными входами — это НЕ. Закон де Моргана: A·B = НЕ(НЕ-A ИЛИ НЕ-B), то есть И = ИЛИ-НЕ от инверсий. Нужно: НЕ-S, НЕ-D0, НЕ-D1; затем D0·НЕ-S и D1·S; наконец их ИЛИ = НЕ от ИЛИ-НЕ. Всего семь элементов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'sr-nor', 0, 'lab', 'SR-защёлка: первая память', 'Соберите защёлку из двух ИЛИ-НЕ крест-накрест: выход каждого подаётся на вход другого. R — сброс, S — установка. Провода могут идти «назад» — циклы здесь разрешены!', '', 'Два ИЛИ-НЕ: Q = НЕ(R ИЛИ nQ), nQ = НЕ(S ИЛИ Q). S подайте на тот элемент, чей выход идёт в nQ. Проверяйте каждый шаг по списку ниже.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'sr-nand', 1, 'lab', 'SR-защёлка на И-НЕ', 'Та же память, но на элементах И-НЕ — и с «обратной» логикой: сигналы активны НУЛЁМ. nS = 0 устанавливает Q = 1, nR = 0 сбрасывает Q = 0, а покой — это nS = nR = 1. Крест-накрест: Q = И-НЕ(nS, nQ), nQ = И-НЕ(nR, Q).', '', 'Два И-НЕ крест-накрест: nS подайте на элемент, выход которого идёт в Q; nR — на элемент, выход которого идёт в nQ. Если И-НЕ закрыт — собирайте его из И и НЕ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'sr-set-first', 2, 'lab', 'Защёлка с приоритетом установки', 'В обычной SR-защёлке S = R = 1 запрещено. Сделайте защёлку, где при S = R = 1 побеждает УСТАНОВКА: Q = 1. Один выход Q. Собирайте вокруг одного цикла: «Q сам себя удерживает, пока нет сброса».', '', 'Q = S ИЛИ (НЕ-R И Q). Выход Q возвращается на вход элемента И — это и есть обратная связь. Три элемента: НЕ, И, ИЛИ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'sr-reset-first', 3, 'lab', 'Защёлка с приоритетом сброса', 'Зеркальная задача: при S = R = 1 побеждает СБРОС — Q = 0. Остальное, как в обычной защёлке. Подумайте, в какой точке цепочки теперь нужно «вставить» R.', '', 'Теперь И стоит ПОСЛЕ ИЛИ: Q = НЕ-R И (S ИЛИ Q). Сначала «установка или удержание», потом сброс всё перебивает.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'sr-gated', 4, 'lab', 'SR-защёлка с разрешением', 'Добавьте вход разрешения E: команды S и R действуют, только пока E = 1. При E = 0 защёлка заперта и хранит значение, что бы ни творилось на S и R.', '', 'Перед обычной SR на ИЛИ-НЕ поставьте два элемента И: S'' = S·E и R'' = R·E. Дальше — крест-накрест, как в первом упражнении раздела. Не открывайте E при S = R = 1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'alarm', 5, 'lab', 'Сигнализация', 'Охранная система: «Sen» — датчик, «Arm» — режим «на охране», «Rst» — сброс. Тревога Q включается, только если датчик сработал НА ОХРАНЕ, и держится, даже когда датчик замолчал — пока её не сбросят.', '', 'Это SR-защёлка на ИЛИ-НЕ: S'' = Sen·Arm (датчик И охрана), R = Rst. Q берите с выхода того элемента, который при установке даёт единицу.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'd-latch', 6, 'lab', 'D-защёлка: память с разрешением', 'Добавьте к защёлке вход разрешения E: пока E = 1, выход Q повторяет данные D («прозрачна»); при E = 0 защёлка «запирается» и хранит записанное значение.', '', 'Возьмите SR-защёлку на NOR и управляйте ею так: S = D И E, R = НЕ-D И E. Понадобятся два элемента И (или И-НЕ с инвертором) и один НЕ плюс два NOR крест-накрест.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'd-latch-nand', 7, 'lab', 'D-защёлка на И-НЕ', 'Классическая схема D-защёлки — четыре И-НЕ (и один инвертор на D). Поведение то же: E = 1 — Q повторяет D, E = 0 — Q хранит. Только теперь «ключи» стоят на И-НЕ и сразу работают как активный ноль для защёлки.', '', 'Два «ключа»: s = И-НЕ(D, E) и r = И-НЕ(НЕ-D, E). Они дают активные нули. Затем защёлка на И-НЕ: Q = И-НЕ(s, nQ), nQ = И-НЕ(r, Q).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'd-clear', 8, 'lab', 'D-защёлка с очисткой', 'У D-защёлки появляется ещё один вход — CLR (очистка). При CLR = 1 защёлка немедленно сбрасывается в Q = 0 и ИГНОРИРУЕТ данные и разрешение. При CLR = 0 — обычная D-защёлка (E = 1 — повторяет D, E = 0 — хранит).', '', 'Усилите сброс и ослабьте установку: R'' = НЕ-D·E ИЛИ CLR, S'' = D·E·НЕ-CLR. Дальше — SR-защёлка на ИЛИ-НЕ. Ключ «НЕ-CLR» выключает установку, пока идёт очистка.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'd-latch-2bit', 9, 'lab', 'Двухбитный регистр', 'Одной D-защёлки мало: числа состоят из нескольких бит. Соберите регистр на два бита — две D-защёлки с ОБЩИМ входом разрешения E. Данные — D1 D0, выходы — Q1 Q0.', '', 'Для каждого бита — своя D-защёлка из прошлых упражнений (НЕ, два И, два ИЛИ-НЕ), но разрешение E у обеих одно: провод от E идёт к элементам И обеих защёлок.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'd-latch-src', 10, 'lab', 'Защёлка с выбором источника', 'Регистру часто нужно записывать данные из одного из двух источников. D0 или D1 выбирает S (0 → D0, 1 → D1); E = 1 записывает выбранное значение в защёлку. Выход Q.', '', 'Склейте два готовых блока: мультиплексор (D0·НЕ-S ИЛИ D1·S) выдаёт одно значение D, а дальше — D-защёлка с входами D и E (два И, НЕ, два ИЛИ-НЕ).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 8, 'mem-cell', 11, 'lab', 'Ячейка памяти: запись и чтение', 'Финал раздела — одноразрядная ячейка памяти. D — данные, W — запись (write), R — чтение (read). Q — содержимое ячейки. Out — то, что видит шина: Out = Q при R = 1, иначе 0. Чтение не должно менять содержимое.', '', 'Хранилище — D-защёлка с разрешением W (НЕ, два И, два ИЛИ-НЕ). Её выход Q пропустите через элемент И вместе с R — это «затвор чтения». Q выведите прямо с защёлки, Out — с затвора.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'increment', 0, 'lab', 'Инкрементер: +1', 'К одноразрядному числу A прибавляем единицу: 0 + 1 = 01, 1 + 1 = 10. S — бит суммы, P — перенос. Присмотритесь к таблице: она проще, чем кажется.', '', 'Перенос P просто повторяет A (провод), а сумма S — это НЕ A. Два элемента — и сумматор готов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'half-adder', 1, 'lab', 'Полусумматор', 'Сложите два бита A и B столбиком: S — бит суммы, P — перенос. Сумма равна 1, когда входы РАЗНЫЕ; перенос — когда оба равны 1.', '', 'S — это XOR из раздела «Простые схемы»: (A ИЛИ B) И НЕ(A И B) — или готовый элемент, если он уже открыт. А P — обычный элемент И на тех же входах: единица только в строке 1 1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'full-adder-sum', 2, 'lab', 'Полный сумматор: бит суммы', 'Теперь складываются ТРИ бита: A + B + Cin (перенос из предыдущего разряда). Соберите бит суммы S: он равен 1, когда единиц среди входов НЕЧЁТНОЕ число.', '', 'Складывайте по очереди: сначала A⊕B, затем результат ⊕ Cin. Каждый XOR — четыре элемента из И/ИЛИ/НЕ — или один готовый XOR (или XNOR: цепочка XNOR из трёх входов даёт ту же чётность).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'full-adder', 3, 'lab', 'Полный сумматор', 'Финал раздела: полный сумматор целиком. S — бит суммы, P — перенос выхода. Перенос равен 1, когда единиц не меньше двух.', '', 'Соедините два готовых куска: S = A⊕B⊕Cin (прошлое упражнение — XOR/XNOR теперь в палитре) и P = AB ИЛИ AC ИЛИ BC (мажоритарная схема из «Простых схем»). Выходы обоих кусков идут в S и P.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'half-subtractor', 4, 'lab', 'Полувычитатель', 'Вычтите бит B из бита A: R — бит разности, Bo — заём (borrow). Заём нужен, когда из 0 вычитают 1: 0 − 1 = −1, и нужно «занять» единицу у старшего разряда.', '', 'Разность — снова XOR: она 1, когда биты разные. А заём — единица только в строке A = 0, B = 1: это НЕ-A И B.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'full-subtractor', 5, 'lab', 'Полный вычитатель', 'Вычитаем три бита: A − B − Bin, где Bin — заём из младшего разряда. R — бит разности, Bo — заём в старший разряд. Заём нужен, когда результат отрицательный.', '', 'Разность — чётность, как у полного сумматора: R = A⊕B⊕Bin. Заём: Bo = НЕ-A·B ИЛИ НЕ(A⊕B)·Bin — «сам занял» или «долг от младшего разряда не покрыт». Короче: Bo — это «хотя бы две единицы» среди НЕ-A, B и Bin.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'increment2', 6, 'lab', 'Двухбитный инкрементер', 'К двухбитному числу A1 A0 прибавьте единицу. P — перенос в третий разряд, S1 S0 — сумма: 00 → 01, 01 → 10, 10 → 11, а 11 + 1 = 100 (переполнение: P = 1, S = 00).', '', 'Младший бит всегда переворачивается: S0 = НЕ-A0. Старший переворачивается, только если младший был 1: S1 = A1⊕A0. Перенос выходит, когда оба были 1: P = A1·A0.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'comparator1', 7, 'lab', 'Однобитный компаратор', 'Сравните два бита A и B тремя выходами: Lt горит, когда A < B; Eq — когда A = B; Gt — когда A > B. Всегда горит ровно один.', '', 'A < B — только строка A = 0, B = 1: НЕ-A И B. A > B — зеркально: A И НЕ-B. Равенство — готовый XNOR (или НЕ от XOR).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'adder2', 8, 'lab', 'Двухбитный сумматор', 'Сложите двухбитные числа A1 A0 и B1 B0. Результат — трёхбитный: P S1 S0 (P — перенос из старшего разряда). Например, 11 + 11 = 110.', '', 'Младший разряд — полусумматор: S0 = A0⊕B0, перенос c = A0·B0. Старший — полный сумматор с входом c: S1 = A1⊕B1⊕c, P = A1·B1 ИЛИ (A1⊕B1)·c. Перенос из младшего разряда «переезжает» в старший.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'add-sub', 9, 'lab', 'Сумматор-вычитатель', 'Один сумматор — и сложение, и вычитание. M — режим: M = 0 даёт A + B; M = 1 даёт A − B как A + НЕ-B + 1 (инвертируем B, а единицу подаём на вход переноса). S — бит результата, P — перенос; при M = 1 единица в P означает «заёма нет».', '', 'Управляемый инвертор из раздела мультиплексоров: B⊕M. Дальше — полный сумматор с входами A, (B⊕M) и Cin = M: S = A⊕(B⊕M)⊕M, P — мажоритарная функция тех же трёх.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'comparator2', 10, 'lab', 'Двухбитный компаратор', 'Сравните двухбитные числа A1 A0 и B1 B0: Lt — A меньше B, Eq — равны, Gt — A больше B. Горит ровно один выход.', '', 'Сравнивайте со старшего разряда. Eq: оба разряда совпали (два XNOR и И). Gt: A1 > B1 ИЛИ (A1 = B1 И A0 > B0). Lt — зеркально.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 9, 'adder3', 11, 'lab', 'Трёхбитный сумматор', 'Финал раздела: сложите числа A2 A1 A0 и B2 B1 B0. Результат — четыре бита P S2 S1 S0. Цепочка переносов должна пройти через все три разряда.', '', 'Три звена: младшее — полусумматор (S0 = A0⊕B0, c0 = A0·B0); два следующих — полные сумматоры: S = A⊕B⊕c, перенос = A·B ИЛИ (A⊕B)·c. Перенос каждого звена идёт на вход следующего; перенос последнего — это P. Инверторы не нужны.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'clocked-latch', 0, 'lab', 'Защёлка под управлением такта', 'Тактовый сигнал CLK — это просто провод, который то поднимается в 1, то опускается в 0. Подайте его на вход разрешения D-защёлки: пока CLK = 1, защёлка открыта и повторяет D, когда CLK = 0 — хранит.', '', 'Это обычная D-защёлка из прошлого раздела: S = D·CLK, R = НЕ-D·CLK, дальше два ИЛИ-НЕ крест-накрест. Роль разрешения E играет CLK.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'latch-low', 1, 'lab', 'Защёлка, открытая при низком такте', 'Сделайте зеркальную защёлку: открыта, пока CLK = 0 (повторяет D), и заперта, когда CLK = 1 (хранит). Это половина будущего триггера.', '', 'Нужен инвертор на такте: E = НЕ-CLK. Остальное — та же D-защёлка (два И, НЕ на D, два ИЛИ-НЕ), только вместо CLK в «ключи» идёт НЕ-CLK.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'dff', 2, 'lab', 'D-триггер по фронту', 'Поставьте защёлки друг за другом: «ведущая» открыта при CLK = 0 и принимает D, «ведомая» открыта при CLK = 1 и берёт значение у ведущей. Выход Q меняется только в момент подъёма CLK с 0 на 1 — по ФРОНТУ. Q и nQ — на выходах ведомой защёлки.', '', 'Ведущая — из прошлого упражнения (E = НЕ-CLK): НЕ на CLK, НЕ на D, два И с НЕ-CLK, два ИЛИ-НЕ. Ведомая — защёлка с E = CLK, её данные D — это выход Q ведущей. Выходы Q и nQ берите с ведомой. Всего около десяти элементов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'toggle', 3, 'lab', 'Делитель на два', 'Соедините выход триггера с его же входом D через инвертор: D = НЕ-Q. Каждый фронт CLK будет переворачивать Q. Нажимайте «Такт» — Q должен идти 1, 0, 1, 0. Готовый триггер при включении стоит в нуле.', '', 'Два элемента: DFF и НЕ. Выход DFF идёт на вход НЕ, а выход НЕ — обратно на вход D триггера. На CLK триггера подайте такт.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'reg1-load', 4, 'lab', 'Регистр с записью по разрешению', 'Хранить значение, пока команды нет, и записывать новое только по LD = 1: при фронте CLK Q берёт D, если LD = 1, и остаётся прежним, если LD = 0. Разрешение записи есть у любого регистра процессора.', '', 'Перед входом D триггера поставьте мультиплексор: D'' = LD·D ИЛИ НЕ-LD·Q. При LD = 0 триггер получает свой же выход — и значение не меняется. Выход Q триггера возвращается в мультиплексор.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'reg-clear', 5, 'lab', 'Синхронный сброс', 'Добавьте регистру вход очистки CLR: при CLR = 1 на ближайшем фронте Q становится 0 (иначе Q берёт D). Сброс «синхронный»: сам по себе, без такта, ничего не меняется.', '', 'Данные для триггера: D'' = D·НЕ-CLR. Пока CLR = 1, на входе триггера ноль — и ближайший фронт запишет его.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'register4', 6, 'lab', 'Четырёхбитный регистр', 'Одно слово — четыре бита D3…D0. Соберите регистр: на каждый разряд — свой триггер, такт у всех общий. На фронте CLK регистр захватывает всё число сразу; между фронтами хранит его, как бы ни менялись входы.', '', 'Четыре элемента DFF. Их входы D — это D3…D0, входы такта у всех подключены к одному CLK, а выходы идут на Q3…Q0. Тактовый провод разветвляется.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'shift4', 7, 'lab', 'Сдвиговый регистр', 'Соедините четыре триггера цепочкой: вход Din идёт в первый, выход первого — во второй, и так далее. На каждом фронте число сдвигается на один разряд, а справа входит новый бит Din. Q0 — самый «свежий» бит, Q3 — самый старый.', '', 'Четыре DFF, тактовые входы объединены. Din → D первого; Q первого → D второго; Q второго → D третьего; Q третьего → D четвёртого. Q0 — выход первого триггера, Q3 — четвёртого.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'counter2', 8, 'lab', 'Двухбитный счётчик', 'Соберите счётчик по модулю 4: после каждого фронта Q1 Q0 растёт на единицу — 00, 01, 10, 11, снова 00. Это «инкрементер» из раздела сумматоров, замкнутый на регистр.', '', 'Нужны два триггера. Младший: D0 = НЕ-Q0 (переворачивается каждый такт). Старший: D1 = Q1⊕Q0 (переворачивается, только когда Q0 = 1). Выходы триггеров Q0 и Q1 возвращаются на входы логики.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'counter-en', 9, 'lab', 'Счётчик с разрешением', 'Счётчик, который считает только пока EN = 1. При EN = 0 фронт ничего не меняет — Q1 Q0 остаются прежними. Так можно «остановить» счёт, не трогая такт.', '', 'Тот же счётчик, но «+1» заменено на «+EN»: D0 = Q0⊕EN; D1 = Q1⊕(Q0·EN). При EN = 0 каждое XOR с нулём возвращает то же значение — разряд не меняется.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'johnson2', 10, 'lab', 'Счётчик Джонсона', 'Хитрый счётчик на двух триггерах и ОДНОМ инверторе: Q1 берёт предыдущее Q0, а Q0 берёт НЕ-Q1. Состояния идут по кругу: 00 → 01 → 11 → 10 → 00. Между соседними состояниями меняется только один бит.', '', 'Это сдвиговый регистр из двух триггеров, у которого вход — НЕ от последнего выхода: D0 = НЕ-Q1, D1 = Q0. Выход Q1 уходит и на выход, и на инвертор.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 10, 'accumulator', 11, 'lab', 'Аккумулятор', 'Финал раздела — «мозг» арифметического цикла. Двухбитный регистр Q1 Q0 хранит накопленное число. На каждом фронте к нему прибавляется входное число IN1 IN0 (по модулю 4), и сумма записывается обратно в регистр. Сумматор и регистр замыкаются в петлю.', '', 'Двухбитный сумматор из прошлого раздела: S0 = Q0⊕IN0, перенос c = Q0·IN0, S1 = Q1⊕IN1⊕c. Суммы S0 и S1 подайте на D двух триггеров, а выходы Q0 и Q1 — обратно на вход сумматора. Старший перенос просто не используется.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'logic-select', 0, 'lab', 'Выбор операции: И или ИЛИ', 'Простейшее АЛУ умеет две операции над битами A и B. Вход Op выбирает, какую: Op = 0 — выход Y = A И B, Op = 1 — Y = A ИЛИ B. Обе операции считаются всегда, а до выхода доходит только выбранная.', '', 'Два вычислителя — A И B и A ИЛИ B — и мультиплексор на выходе: Y = НЕ-Op·(A·B) ИЛИ Op·(A+B). Мультиплексор вы собирали в разделе про выбор сигналов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'logic4', 1, 'lab', 'Четыре логические операции', 'Добавьте ещё операций. Код Op1 Op0 выбирает: 00 — A И B, 01 — A ИЛИ B, 10 — A XOR B, 11 — НЕ A (B игнорируется). Выход Y — результат выбранной операции.', '', 'Четыре вычислителя (И, ИЛИ, XOR, НЕ-A) и мультиплексор 4→1 по Op1 Op0 — дерево из трёх мультиплексоров 2→1, как в разделе про выбор сигналов. Если XOR закрыт, соберите его из И, ИЛИ и НЕ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'flags2', 2, 'lab', 'Флаги результата', 'АЛУ не просто выдаёт число — оно сообщает о нём «флаги». По двухбитному результату R1 R0 выдайте три: Z — результат равен нулю; N — отрицательный (старший бит в дополнительном коде — знак); Pe — число единиц в результате чётное.', '', 'Z — один элемент ИЛИ-НЕ: ноль, когда оба бита нули. N — просто провод от R1. Pe — равенство битов (XNOR): чётное число единиц, когда они одинаковые.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'incdec2', 3, 'lab', 'Инкремент и декремент', 'Два специальных действия АЛУ: «+1» и «−1». Двухбитное A1 A0 меняется на единицу в обе стороны по кругу: при Dec = 0 результат A + 1 (11 → 00), при Dec = 1 — A − 1 (00 → 11). Выход R1 R0.', '', 'Младший бит переворачивается всегда: R0 = НЕ-A0. Старший: при +1 он переворачивается, если A0 = 1 (R1 = A1⊕A0); при −1 — если A0 = 0 (R1 = A1⊕НЕ-A0 = A1⊕A0⊕1). Оба случая объединяются: R1 = A1⊕A0⊕Dec.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'overflow2', 4, 'lab', 'Флаг переполнения', 'Двухбитные числа со знаком (в дополнительном коде) лежат в диапазоне от −2 до 1: 00 = 0, 01 = 1, 10 = −2, 11 = −1. Сложите A и B и выдайте V = 1, если истинный результат в этот диапазон НЕ помещается (например, 01 + 01 = 2 — переполнение).', '', 'Переполнение бывает, только когда знаки слагаемых одинаковые (A1 = B1), а знак суммы S1 — другой. Для S1 нужен перенос из младшего разряда c = A0·B0: S1 = A1⊕B1⊕c. Тогда V = (A1 ⊙ B1) · (A1 ⊕ S1).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'shifter2', 5, 'lab', 'Сдвигатель', 'Сдвиг — тоже операция АЛУ: умножение или деление на два. Двухбитное A1 A0 сдвигается влево (Dir = 0: R = A0 0) или вправо (Dir = 1: R = 0 A1). Бит, который «выпал», уходит на выход Co.', '', 'Каждый выход — выбор по Dir. R1 = НЕ-Dir·A0 (при сдвиге вправо старший бит — ноль); R0 = Dir·A1; Co = НЕ-Dir·A1 ИЛИ Dir·A0. Один инвертор на Dir.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'alu-slice', 6, 'lab', 'Разряд АЛУ', 'Соберите один разряд АЛУ. Входы: A, B, перенос Cin и код операции Op1 Op0 — 00 сложение (A + B + Cin), 01 вычитание (A + НЕ-B + Cin), 10 — A И B, 11 — A ИЛИ B. Выходы: бит результата R и перенос Co (у логических операций Co = 0).', '', 'Три блока. Арифметика: bx = B⊕Op0 (инверсия B при вычитании), затем полный сумматор A, bx, Cin. Логика: мультиплексор И / ИЛИ по Op0. Итог: мультиплексор по Op1 — арифметика (Op1 = 0) или логика (Op1 = 1). Перенос Co берите только при Op1 = 0.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'alu2-arith', 7, 'lab', 'Арифметика: сложение и вычитание', 'Арифметический блок двухбитного АЛУ. Режим M = 0 — A + B, M = 1 — A − B (то есть A + НЕ-B + 1). Выходы: R1 R0 — результат, Co — перенос из старшего разряда (при вычитании Co = 1 означает «заёма нет», то есть A ≥ B).', '', 'Управляемый инвертор на B: bm = B⊕M для каждого разряда. Дальше двухбитный сумматор из прошлого раздела, но перенос на входе младшего разряда равен M: R0 = A0⊕bm0⊕M, c0 = A0·bm0 ИЛИ (A0⊕bm0)·M, далее старший разряд как обычно.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'alu2-bitwise', 8, 'lab', 'Логика на два разряда', 'Логический блок двухбитного АЛУ. Вход Op выбирает операцию над каждой парой бит: Op = 0 — поразрядное И, Op = 1 — поразрядное ИЛИ. Выход R1 R0.', '', 'Два одинаковых «разряда» с общим Op: в каждом считаются И и ИЛИ, а мультиплексор по Op выбирает одно из них. Инвертор на Op нужен один на оба разряда.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'alu2', 9, 'lab', 'Двухбитное АЛУ', 'Финал: соедините арифметику и логику. Код Op1 Op0 выбирает операцию над A1 A0 и B1 B0: 00 — A + B, 01 — A − B, 10 — A И B, 11 — A ИЛИ B. Выход R1 R0 — результат (по модулю 4).', '', 'Не собирайте всё заново — это те же два блока. Арифметика: M = Op0, результат R1 R0 из прошлого упражнения (Co не нужен). Логика: Op = Op0. Затем на каждом выходе — мультиплексор по Op1: арифметика при Op1 = 0, логика при Op1 = 1. Всего около тридцати элементов — собирайте по частям.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'compare-sub', 10, 'lab', 'Сравнение через вычитание', 'Как процессор сравнивает числа? Вычитает и смотрит на результат! Для двухбитных беззнаковых A и B выдайте Lt (A < B), Eq (A = B), Gt (A > B), используя вычитание A − B = A + НЕ-B + 1.', '', 'Вычитатель: nb = НЕ-B. Младший разряд с переносом 1 упрощается: R0 = A0⊙nb0, c0 = A0 ИЛИ nb0. Старший: x = A1⊕nb1, R1 = x⊕c0, Co = A1·nb1 + x·c0. Затем: Eq = НЕ(R1+R0) (разность нулевая), Lt = НЕ-Co (был заём), Gt = Co·НЕ-Eq.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 11, 'branch-cond', 11, 'lab', 'Условие перехода', 'Флаги нужны, чтобы решать, идти ли программе дальше или перепрыгнуть. По флагам Z (ноль), N (знак), V (переполнение) и коду условия C1 C0 выдайте T — «условие выполнено»: 00 — «равно» (Z), 01 — «не равно» (НЕ-Z), 10 — «меньше» (N⊕V), 11 — «меньше или равно» (Z ИЛИ N⊕V).', '', 'Сначала посчитайте все четыре условия: Z, НЕ-Z, lt = N⊕V и le = Z ИЛИ lt. Затем мультиплексор 4→1 по C1 C0 выбирает одно — дерево из трёх мультиплексоров 2→1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 12, 'rom4x2', 0, 'lab', 'ПЗУ: четыре слова', 'ПЗУ (постоянное запоминающее устройство) — память, содержимое которой «зашито» в схему. По адресу A1 A0 оно выдаёт слово D1 D0: по адресу 0 — 10, по адресу 1 — 01, по адресу 2 — 11, по адресу 3 — 00.', '', 'Это обычная таблица истинности: адрес — входы, слово — выходы. Столбец D1 = [1, 0, 1, 0] — это НЕ-A0. Столбец D0 = [0, 1, 1, 0] — XOR адресных битов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 12, 'rom4x4', 1, 'lab', 'ПЗУ с программой', 'Запишите в ПЗУ программу из четырёх команд (по 4 бита, выходы W3…W0): по адресу 0 — 0010, по адресу 1 — 0101, по адресу 2 — 1001, по адресу 3 — 1100. Позже процессор прочитает её по очереди и выполнит.', '', 'Дешифратор адреса 2→4 (Y0…Y3 — «сработал адрес k»), а каждый бит слова — ИЛИ тех адресов, где он равен 1. W3 = Y2 ИЛИ Y3, W2 = Y1 ИЛИ Y3, W0 = Y1 ИЛИ Y2, а W1 = Y0 (единица только в слове 0).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 12, 'memory-map', 2, 'lab', 'Карта памяти', 'В компьютере несколько устройств разделяют одно адресное пространство. Три адресных бита A2 A1 A0 (адреса 0…7) выбирают одно из них: ПЗУ — адреса 0…3, ОЗУ — 4…6, порты ввода-вывода — адрес 7. Выдайте сигналы выбора Rom, Ram и Io — горит ровно один.', '', 'ПЗУ — просто НЕ-A2 (весь нижний полуадрес). Порты — адрес 111: A2·A1·A0. ОЗУ — верхний полуадрес, кроме 111: A2 И НЕ(A1·A0).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 12, 'bus-control', 3, 'lab', 'Управление шиной памяти', 'К памяти приходят три сигнала: CS (выбрана ли микросхема), Rd (чтение) и Wr (запись). Выдайте We — разрешение записи (CS и Wr) и Oe — разрешение выдачи данных на шину (CS и Rd). Читать и писать одновременно нельзя: если пришли оба сигнала, запись побеждает, Oe = 0.', '', 'We — один элемент И: CS·Wr. Oe = CS·Rd·НЕ-Wr: сначала CS И Rd, затем результат И НЕ-Wr.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 12, 'protected-cell', 4, 'lab', 'Ячейка с защитой записи', 'Одноразрядная ячейка из защёлки с тремя управляющими сигналами. W — запись (при W = 1 ячейка принимает D), WP — защита записи: при WP = 1 запись запрещена, что бы ни пришло на W. RD — чтение: при RD = 1 значение ячейки выходит на шину Out, иначе Out = 0. Q — само содержимое.', '', 'Разрешение записи для защёлки: we = W·НЕ-WP. Дальше обычная D-защёлка с этим разрешением (НЕ на D, два И, два ИЛИ-НЕ), а Out = Q·RD — затвор чтения, как в ячейке из раздела про защёлки.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 12, 'cell-select', 5, 'lab', 'Память на две ячейки', 'Сложите две ячейки из D-защёлок в память. Вход A — адрес ячейки (0 или 1), W — запись, D — данные. Запись идёт только в адресованную ячейку; на выход Q всегда выходит содержимое адресованной ячейки. Свежая ячейка пуста — выход «?».', '', 'Адрес разрешает запись только в одну ячейку: w0 = W·НЕ-A, w1 = W·A. Каждая ячейка — D-защёлка с разрешением w0 или w1 (НЕ на D, два И, два ИЛИ-НЕ). Чтение — мультиплексор по A между Q ячеек. Всего около 16 элементов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 12, 'ram2x2', 6, 'lab', 'ОЗУ: два слова по два бита', 'Расширьте память до двухбитных слов. Данные D1 D0, адрес слова A (0 или 1), запись W; выход Q1 Q0 — слово по адресу. Запись обновляет оба бита адресованного слова сразу. Незаписанное слово — «?».', '', 'Четыре ячейки (по две на слово). Разрешение записи для слова 0: W·НЕ-A, для слова 1: W·A — оно общее для обоих битов слова. Данные D1 и D0 идут каждый в свою пару ячеек (НЕ на каждый бит — общий для обеих ячеек). Чтение — по мультиплексору на каждый бит. Около 27 элементов — собирайте по слоям.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 12, 'sync-cell', 7, 'lab', 'Синхронная память', 'В настоящих процессорах память пишут по такту. Соберите память из двух ячеек на триггерах DFF: данные D записываются в ячейку с адресом A только по фронту CLK и только при W = 1. Выход Q — содержимое адресованной ячейки. Готовые триггеры при включении стоят в нуле.', '', 'Каждая ячейка — DFF с «удержанием» на входе: D'' = w ? D : Q, где w = W·(A = k). Это мультиплексор «себя или новое» из упражнения про регистр с записью. Читает память мультиплексор по A. Около 16 элементов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 13, 'control-word', 0, 'lab', 'Управляющее слово', 'Набор команд процессора: 00 — LDI k (загрузить), 01 — ADD k (прибавить), 10 — JNZ k (прыжок, если не ноль), 11 — HLT (стоп). По коду операции I3 I2 выдайте четыре управляющих сигнала: Ld — «записать результат в аккумулятор» (LDI и ADD), Add — «прибавить к текущему значению» (только ADD), Jmp — «это прыжок» (JNZ), Hlt — «стоп» (HLT).', '', 'Ld = НЕ-I3 (команды 00 и 01 — это I3 = 0). Add = НЕ-I3·I2, Jmp = I3·НЕ-I2, Hlt = I3·I2 — каждый «узнаёт» свой код, как выход дешифратора.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 13, 'jnz-take', 1, 'lab', 'Условный переход', 'Команда JNZ прыгает, только если аккумулятор НЕ ноль. Флаг Z = 1 означает «аккумулятор равен нулю» (из раздела про АЛУ). К четырём сигналам прошлого упражнения добавьте решение о прыжке: Take = 1, если команда JNZ и Z = 0. Теперь выходы: Ld, Add, Take, Hlt.', '', 'Ld, Add и Hlt те же, что в прошлом упражнении. Take = Jmp·НЕ-Z, где Jmp = I3·НЕ-I2: сначала «это JNZ», затем «и аккумулятор не ноль».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 13, 'acc-operand', 2, 'lab', 'Операнд для аккумулятора', 'Что записать в аккумулятор? Для LDI — просто операнд k; для ADD — сумму ACC + k. Сигнал Add (из декодера) решает, прибавлять ли аккумулятор. Входы: ACC (A1 A0), операнд k (K1 K0), Add. Выход R1 R0 = K + (Add ? ACC : 0), по модулю 4.', '', 'Сначала «затвор»: g1 = A1·Add, g0 = A0·Add — при Add = 0 вместо аккумулятора нули. Потом двухбитный сумматор K + g: R0 = K0⊕g0, c = K0·g0, R1 = K1⊕g1⊕c.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 13, 'next-pc', 3, 'lab', 'Следующий адрес', 'Счётчик команд (PC) хранит адрес текущей команды. Следующий адрес — либо «адрес + 1», либо адрес прыжка k, если решено прыгать (Take = 1). Входы: Take, K1 K0 (куда прыгать), P1 P0 (текущий адрес). Выход N1 N0 — следующий адрес (по модулю 4).', '', 'Два пути, выбор по Take. Путь «+1» — инкрементер: i0 = НЕ-P0, i1 = P1⊕P0. Затем на каждый бит мультиплексор: Ni = Take ? Ki : ii.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 13, 'phase-seq', 4, 'lab', 'Фазы такта', 'Команда выполняется не за один такт: сначала выборка (Fe — достать команду из памяти), потом декодирование (De), исполнение (Ex) и запись результата (Wb). Соберите «секвенсор»: счётчик на два бита, который по каждому такту переходит к следующей фазе, и четыре выхода «сейчас эта фаза». Сразу после включения — фаза Fe.', '', 'Счётчик Джонсона из раздела про регистры: D0 = НЕ-Q1, D1 = Q0, состояния 00 → 01 → 11 → 10. Декодируйте: Fe — 00 (ИЛИ-НЕ от Q1, Q0), De — 01, Ex — 11, Wb — 10. Для De и Wb нужны НЕ от Q0 и Q1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 13, 'phase-gate', 5, 'lab', 'Сигналы управления по фазам', 'Управляющие сигналы подаются не всё время, а в «свою» фазу. По фазам Fe и Wb и коду операции I3 I2 выдайте: IrLoad — загрузить регистр команд (в фазе Fe); AccLoad — записать аккумулятор (в фазе Wb, и только для LDI и ADD, то есть при I3 = 0); PcLoad — обновить счётчик команд (в фазе Wb, но НЕ для HLT, чтобы процессор после остановки не шёл дальше).', '', 'IrLoad — просто провод от Fe. AccLoad = Wb·НЕ-I3. Для PcLoad сначала «это HLT» = I3·I2, затем Wb·НЕ(HLT).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 13, 'hlt-latch', 6, 'lab', 'Остановка процессора', 'Когда процессор встречает HLT, он должен остановиться насовсем — не только на момент, пока команда на шине. Соберите защёлку «Run»: Rst = 1 запускает (Run = 1), сигнал Hlt = 1 останавливает (Run = 0), и после этого Run остаётся 0, даже когда Hlt пропал. Только новый Rst снова запустит процессор.', '', 'Это SR-защёлка на двух ИЛИ-НЕ: Q = НЕ(Rst ИЛИ nQ), nQ = НЕ(Hlt ИЛИ Q). Q запоминает «остановлен», а выход Run — это nQ (противоположность Q).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 13, 'decode-all', 7, 'lab', 'Полный декодер', 'Соберите декодер целиком. Входы: I3 I2 (код операции), Z (аккумулятор равен нулю), Wb (фаза записи результата). Выходы: AccLoad — писать в аккумулятор (в Wb, для LDI и ADD); UseAdd — прибавлять аккумулятор (для ADD); Take — прыгать (JNZ и Z = 0); PcLoad — обновить счётчик команд (в Wb, кроме HLT); Stop — команда HLT.', '', 'Это уже собранные куски: Stop = I3·I2; UseAdd = НЕ-I3·I2; Take = I3·НЕ-I2·НЕ-Z; AccLoad = Wb·НЕ-I3; PcLoad = Wb·НЕ-Stop. Остаётся только аккуратно повторно использовать общие инверторы и Stop.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 14, 'reg2-load', 0, 'lab', 'Двухбитный регистр с записью', 'Из двух триггеров DFF соберите регистр на слово из двух бит. По фронту CLK, если LD = 1, регистр берёт слово D1 D0; при LD = 0 хранит прежнее. Из таких регистров потом сложатся аккумулятор и счётчик команд. Готовые триггеры при включении стоят в нуле.', '', 'Два одинаковых разряда с общим LD и CLK: на входе триггера мультиплексор «себя или новое» D'' = LD·D + НЕ-LD·Q (из упражнения «Регистр с записью по разрешению»). Инвертор LD нужен один на оба разряда. Около 10 элементов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 14, 'decode-bus', 1, 'lab', 'Шина: прочитать и декодировать', 'Первое упражнение с блоками. У вас есть ПЗУ с программой (порт addr — адрес, instr — команда) и декодер команд (порты op, z, wb → ctl). Соедините их шинами: по адресу ПЗУ достаёт команду, а декодер превращает её код операции в сигналы управления. Чтобы получить код операции, раскройте порт instr (кнопка ▸) и тяните провод от поля op.', '', 'Четыре провода. Адрес (addr сверху) → вход addr ПЗУ. Поле op выхода instr → вход op декодера. Входы z и wb сверху → входы z и wb декодера. Выход ctl декодера → выход ctl справа. Провод между портами одного типа тянется целиком; несовместимый тип подсветится серым.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 14, 'fetch', 2, 'lab', 'Выборка команд', 'Соберите блок выборки: счётчик команд (регистр на 2 бита), схема «следующий адрес» и ПЗУ с программой. По такту при load = 1 счётчик берёт следующий адрес (+1 или адрес прыжка k, если take = 1), а ПЗУ всё время выдаёт команду по текущему адресу. Регистр хранит слово (Word2), а адрес — это Addr2: между ними понадобятся переходники.', '', 'Регистр reg2 — это счётчик команд. Его выход q (Word2) через переходник «слово → адрес» даёт адрес для ПЗУ, для next-pc (вход pc) и для выхода pc. Выход next-pc (Addr2) через переходник «адрес → слово» идёт на вход d регистра. Остальное: take, k → next-pc; load, clk → регистр; instr ПЗУ → выход instr.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 14, 'exec', 3, 'lab', 'Исполнение', 'Соберите блок исполнения: аккумулятор (регистр на 2 бита), «операнд аккумулятора» (что записывать) и флаги по значению аккумулятора. По такту при acc_load = 1 в аккумулятор записывается либо k (use_add = 0), либо ACC + k (use_add = 1). Выходы: acc — текущее значение и flags — флаги (Z = 1, когда ноль).', '', 'Аккумулятор — reg2. Его выход q идёт в три места: на вход acc блока «операнд», на вход r блока «флаги» и на выход acc. Блок «операнд» получает k и use_add снаружи (вход add), а его выход r — на вход d регистра. acc_load → load регистра, clk → clk регистра. Флаги идут на выход flags.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 14, 'cpu', 4, 'lab', 'Процессор', 'Финал: соберите процессор из четырёх блоков — секвенсор фаз, выборка команд, декодер и исполнение. На входе только такт CLK. ПЗУ внутри блока выборки хранит программу LDI 2, ADD 1, JNZ 1, HLT — процессор выполнит её сам. Каждая команда занимает четыре такта: выборка, декодирование, исполнение, запись. Выходы: acc — аккумулятор, pc — счётчик команд, ph — текущая фаза.', '', 'Такт clk → clk секвенсора, выборки и исполнения. Секвенсор: ph.Wb → wb декодера. Выборка: instr.op → op декодера; instr.k → k исполнения; instr.k через переходник «слово → адрес» → k выборки. Исполнение: flags.Z → z декодера. Декодер: ctl.UseAdd → use_add исполнения, ctl.AccLoad → acc_load исполнения, ctl.Take → take выборки, ctl.PcLoad → load выборки. Наружу: acc, pc и ph.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 15, 'patch-byte', 0, 'lab', 'Поменять один байт', 'На диске по адресу 0x10 лежит строка «Hello» (в конце нулевой байт — признак конца). Замените первую букву на «J», чтобы получилось «Jello». Остальное на диске менять нельзя.', '', 'Нужны три команды: положить в регистр код буквы (li r1, ''J''), положить в другой регистр адрес (li r2, 0x10) и записать байт на диск: sb r1, 0(r2). И не забудьте остановить процессор — hlt.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 15, 'upper', 1, 'lab', 'Заглавные буквы', 'На диске по адресу 0x10 лежит строка «hello, world!» (в конце нулевой байт). Сделайте все латинские буквы заглавными: «HELLO, WORLD!». Запятую, пробел и «!» трогать нельзя. Подсказка из таблицы ASCII: заглавная буква на 32 меньше строчной.', '', 'Идите по строке указателем: lb читает байт, addi r1, r1, 1 двигает указатель. Нулевой байт — конец (beqz r5, конец). Буква строчная, если ''a'' ≤ код ≤ ''z'': пропускайте всё, что меньше ''a'' (bltu) или больше ''z'' (bgtu). Иначе вычтите 32 и запишите обратно.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 15, 'reverse', 2, 'lab', 'Развернуть строку', 'По адресу 0x0F лежит длина строки (6), а с адреса 0x10 — сама строка «abcdef» (без нулевого байта). Разверните её на месте: «fedcba». Дополнительной памяти на диске нет, обменивайте байты попарно с двух концов.', '', 'Два указателя: i на начало, j на конец (адрес 0x10 + длина − 1). Пока i < j: прочитайте оба байта, запишите крест-накрест, i++, j−−. Условие выхода: bgeu r1, r2, конец.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 15, 'max', 3, 'lab', 'Наибольший элемент', 'По адресу 0x0F — количество элементов массива (8), с адреса 0x10 — сами элементы (байты без знака): 23, 7, 200, 56, 91, 3, 150, 77. Найдите наибольший и запишите его по адресу 0x0E.', '', 'Заведите регистр «пока наибольший» (сначала 0) и пройдите по массиву указателем до конца (адрес первого + количество). Если очередной элемент больше — запомните его: bgeu r2, r4, дальше пропускает замену.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 15, 'sort', 4, 'lab', 'Сортировка массива', 'По адресу 0x0F — количество элементов (8), с адреса 0x10 — массив байт без знака: 42, 17, 99, 3, 250, 8, 63, 31. Отсортируйте его на месте по возрастанию: 3, 8, 17, 31, 42, 63, 99, 250.', '', 'Пузырьком: внешний цикл уменьшает «конец» массива на 1 с каждым проходом, внутренний идёт от начала до конца и меняет соседей местами, если левый больше правого (lb r4, 0(r1) и lb r5, 1(r1)). Заканчивайте, когда «конец» дошёл до начала.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 15, 'sum16', 5, 'lab', 'Сумма двухбайтных чисел', 'Числа теперь не помещаются в байт, поэтому каждое занимает два байта: старший байт первым, затем младший (число 0x0123 лежит как 01 23). По адресу 0x0E — размер элемента (2), по 0x0F — количество (5), с 0x10 — сами числа: 0x0123, 0x00FF, 0x01C8, 0x0099, 0x0234. Найдите их сумму и запишите двумя байтами по адресу 0x0C (старший) и 0x0D (младший).', '', 'Складывайте отдельно старшие и отдельно младшие байты. Главное — перенос: когда младшие байты складываются с переходом через 255, результат «заворачивается» и становится МЕНЬШЕ слагаемого. Это и есть признак переноса: если lo после сложения меньше добавленного байта (bltu), прибавьте единицу к старшему байту.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 15, 'max16', 6, 'lab', 'Наибольшее двухбайтное число', 'Тот же формат: по 0x0E — размер элемента (2), по 0x0F — количество (5), с 0x10 — числа (старший байт первым): 0x0102, 0x00FF, 0x0300, 0x02FE, 0x0301. Найдите наибольшее и запишите по адресу 0x0C (старший) и 0x0D (младший).', '', 'Два числа сравнивают как слова в словаре: сначала старшие байты, и только если они равны — младшие. Для каждого числа: старший меньше максимума — пропустить; старший больше — взять новый максимум; равны — сравнить младшие.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 15, 'sort-sized', 7, 'lab', 'Сортировка элементов любого размера', 'Общий случай: по адресу 0x0E лежит размер элемента в байтах (сейчас 2), по 0x0F — количество (6), с 0x10 — массив. Элементы — двухбайтные числа (старший байт первым): 0x0305, 0x0102, 0x02FF, 0x0101, 0x0300, 0x0102. Отсортируйте массив по возрастанию на месте. Программа должна брать размер и количество с диска, а не «знать» их заранее — тогда она подойдёт и для однобайтных, и для трёхбайтных элементов.', '', 'Это та же пузырьковая сортировка, но шаги — не на 1, а на размер элемента S (держите его в регистре): конец массива = начало + N·S (умножение — циклом сложений), соседний элемент — p + S. Элементы сравнивают по байтам слева направо до первого различия, а меняют местами побайтно в цикле на S шагов. Условные переходы доставляют максимум на 31 команду, дальше используйте j.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 16, 'uart-hi', 0, 'lab', 'Привет из UART', 'Мягкий процессор выводит текст через UART — устройство по адресу 0x10000000: байт, записанный (sb) по этому адресу, появляется в консоли. Выведите «Hi!» и перевод строки (всего четыре байта) и остановитесь командой ebreak. Адрес в регистр кладёт li, а код символа можно писать в кавычках: li t1, ''H''.', '', 'Адрес UART — 0x10000000, пусть он лежит в t0. Для каждого символа: li t1, ''H'' и sb t1, 0(t0). Перевод строки — число 10. Последней командой — ebreak.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 16, 'uart-string', 1, 'lab', 'Строка до нулевого байта', 'В памяти (в данных задания) лежит строка msg: «Hello, RISC-V!» с переводом строки и нулевым байтом в конце. Выведите её в UART: идите по строке указателем (lbu читает байт), пока не встретите нуль. Метка msg доступна в вашем коде: la t1, msg.', '', 'Указатель на строку в t1 (la t1, msg). В цикле: lbu t2, 0(t1); если t2 равен нулю (beqz) — конец; иначе sb t2, 0(t0); addi t1, t1, 1; j цикл.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 16, 'leds', 2, 'lab', 'Узор на светодиодах', 'Светодиоды — устройство по адресу 0x10001000: младшие 8 бит записанного слова зажигают LED0…LED7. Зажгите узор 1010 0101 (LED7, LED5, LED2 и LED0), то есть запишите число 0xA5 (sw), и остановитесь.', '', 'li t0, 0x10001000 — адрес светодиодов; li t1, 0xA5 — узор; sw t1, 0(t0).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 16, 'switches-invert', 3, 'lab', 'Переключатели → светодиоды', 'Переключатели — устройство по адресу 0x10001004: чтение даёт их состояние (8 бит). Прочитайте переключатели и зажгите светодиоды (0x10001000) ИНВЕРТИРОВАННЫМ узором: где переключатель включён — светодиод погашен, и наоборот. Сейчас переключатели стоят в положении 1011 0010.', '', 'lw читает переключатели; not (то есть xori с −1) переворачивает все 32 бита, а светодиодам нужны только младшие 8: добавьте andi t2, t2, 0xff (или просто пишите — устройство и так берёт 8 бит).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 16, 'sum-100', 4, 'lab', 'Сумма от 1 до 100', 'Посчитайте сумму всех целых от 1 до 100 циклом и положите результат в регистр a0, затем остановитесь командой ebreak. Ожидаемый ответ — 5050.', '', 'Два регистра: сумма (сначала 0) и счётчик (сначала 1). В цикле: добавить счётчик к сумме, увеличить счётчик, повторять, пока он не превысит 100 (blt счётчик, 101, цикл — предел загрузите в регистр).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 16, 'upper', 5, 'lab', 'Заглавные буквы в памяти', 'В данных задания лежит строка text: «risc-v is fun!» (с нулевым байтом). Сделайте все латинские буквы заглавными прямо в памяти: «RISC-V IS FUN!». Остальные символы (дефис, пробелы, «!») не трогайте. Разница между заглавной и строчной буквой — 32.', '', 'Идите указателем: lbu читает, sb записывает. Буква строчная, если ''a'' ≤ код ≤ ''z'' — пропускайте всё, что меньше ''a'' (bltu) или больше ''z'' (bltu с переставленными регистрами). Иначе вычтите 32 и запишите обратно.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 16, 'factorial', 6, 'lab', 'Факториал: функция и стек', 'Напишите рекурсивную функцию fact(n) = n! и вызовите её с n = 6: результат (720) должен оказаться в a0. Соглашение о вызовах: аргумент и результат — в a0; адрес возврата ra функция должна сохранить на стеке перед вызовом самой себя; стек растёт вниз (sp уменьшается). Главная программа уже вызывает fact — допишите функцию. В конце стек должен вернуться на место.', '', 'Начало функции: addi sp, sp, -16; sw ra, 12(sp); sw s0, 8(sp); mv s0, a0 (n сохраняем в s0 — этот регистр «неприкосновенный»). Если n < 2 — вернуть 1. Иначе: a0 = n − 1; call fact; mul a0, a0, s0. Конец: lw s0, 8(sp); lw ra, 12(sp); addi sp, sp, 16; ret.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 16, 'sort-words', 7, 'lab', 'Сортировка массива слов', 'В данных задания: n — количество элементов (8) и arr — массив 32-битных СЛОВ со знаком: 5, −3, 99, 0, −100, 42, 7, −1. Отсортируйте массив по возрастанию на месте. Слова лежат по четыре байта, поэтому адрес i-го элемента — arr + 4·i (сдвиг slli на 2). Сравнивайте со знаком (blt/bge), иначе отрицательные числа окажутся «самыми большими».', '', 'Пузырёк, как в Мини-8, но шаг — четыре байта: lw t3, 0(t2) и lw t4, 4(t2) читают соседей, sw возвращает их в обратном порядке. Номер элемента умножайте на 4 через slli.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 16, 'timer-blink', 8, 'lab', 'Мигание по таймеру', 'Таймер — устройство по адресу 0x10002000: чтение даёт число выполненных команд. Заставьте LED0 мигать: восемь переключений подряд (включить, выключить, включить…), и каждое состояние должно держаться не меньше 200 тактов. Задержку делайте ожиданием: запомните время, затем читайте таймер, пока он не уйдёт вперёд на 200.', '', 'Цикл из восьми проходов: запишите в светодиоды 1 или 0 (t3 переворачивайте xori t3, t3, 1); запомните время lw t4, 0(t1); прибавьте 200; в цикле ожидания читайте таймер и сравнивайте с пределом (bltu).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 17, 'real-hello', 0, 'lab', 'Hello из настоящего write', 'Теперь без периферии учебной платы: это обычная программа. Точка входа — метка _start, строка лежит в секции .rodata. Выведите её системным вызовом write(fd = 1, буфер, длина): номер вызова 64 кладётся в a7, аргументы — в a0, a1, a2, потом ecall. Затем завершите программу вызовом exit(0): a7 = 93, a0 = код возврата. Сборка у себя: make run (описание ниже).', '', 'a0 = 1 (стандартный вывод), a1 = адрес строки (la a1, msg), a2 = её длина (15 байт вместе с переводом строки), a7 = 64, ecall. Затем li a0, 0; li a7, 93; ecall.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 17, 'real-print-uint', 1, 'lab', 'Печать числа: print_uint', 'write умеет выводить только байты, поэтому число нужно превратить в текст самому. Допишите функцию print_uint(a0): она печатает беззнаковое число в десятичном виде и перевод строки. Основная программа уже вызывает её для 0, 7, 1234567 и 4294967295. Алгоритм: пока число не стало нулём — взять остаток от деления на 10 (remu), прибавить код символа «0», записать в буфер на стеке и разделить число на 10 (divu). Цифры получаются с конца, поэтому буфер заполняется справа налево.', '', 'Выделите на стеке 16 байт (addi sp, sp, -16), положите в конец перевод строки (10) и пишите цифры, уменьшая указатель. Число 0 — особый случай: цикл должен выполниться хотя бы раз (проверка условия в конце цикла, как do…while). В конце — write(1, начало, длина) и addi sp, sp, 16 перед ret.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 17, 'real-fizzbuzz', 2, 'lab', 'FizzBuzz', 'Классика: для чисел от 1 до 30 выведите по строке: «FizzBuzz», если число делится и на 3, и на 5; «Fizz» — если только на 3; «Buzz» — если только на 5; иначе само число. Готовая print_int уже есть — она печатает число и перевод строки. Текстовые слова выводите сами через write. Остаток от деления даёт команда rem.', '', 'Счётчик храните в s0 — этот регистр не портится вызовом print_int (вызываемая функция обязана его сохранять; наша print_int вообще его не трогает). Проверяйте сначала деление на 15, потом на 3, потом на 5.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 17, 'real-fib', 3, 'lab', 'Числа Фибоначчи', 'Выведите первые 15 чисел Фибоначчи (0, 1, 1, 2, 3, 5, …, 377), по числу в строке. Готовая print_int уже есть. Каждое следующее число — сумма двух предыдущих, поэтому держите два регистра и обновляйте их в цикле.', '', 'Пусть s0 = текущее число (сначала 0), s1 = следующее (сначала 1), s2 = сколько ещё напечатать. В цикле: напечатать s0; t = s0 + s1; s0 = s1; s1 = t; s2--.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 17, 'real-sort-print', 4, 'lab', 'Отсортировать и напечатать', 'В секции .data лежит массив из восьми 32-битных слов со знаком: 5, −3, 99, 0, −100, 42, 7, −1 (метка arr, число элементов — константа N). Отсортируйте его по возрастанию на месте и напечатайте элементы по одному в строке (готовая print_int печатает и отрицательные числа).', '', 'Сортировка пузырьком, как раньше: адрес i-го слова — arr + 4·i. Для печати пройдите массив ещё раз: lw a0, 0(указатель); call print_int. Счётчики и указатели, которые должны пережить call, держите в s-регистрах.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (14, 17, 'real-exit-code', 5, 'lab', 'Код возврата: гласные', 'Программа может сообщить результат кодом возврата: он лежит в a0 при вызове exit, а в терминале его показывает «echo $?». Посчитайте, сколько в строке text английских гласных (a, e, i, o, u — строчных; строка заканчивается нулевым байтом), и верните это число как код возврата. Ничего выводить не нужно.', '', 'Идите по строке lbu до нулевого байта. Для каждого символа сравнивайте по очереди с пятью гласными (beq) и увеличивайте счётчик. Результат — в a0, затем li a7, 93; ecall.', '{}');
